inline flight::Ref<flight::types::Matrix> get_node_local_matrix(flight::types::Node2D target) {
  using Runtime = std::shared_ptr<flight::types::NodeRuntime<flight::Ref<flight::types::Node2DTraits>>>;
  auto runtime = flight::node::native_node_2d_runtime(target);
  if (runtime->local_transform_using_local_transform_id == runtime->local_transform_id && runtime->local_matrix) return *runtime->local_matrix;
  const auto value = [&]<typename Key>() { return flight::row_get<Key>(target); };
  const double rotation = value.template operator()<flight::RowKey<"rotation">>();
  if (rotation != runtime->rotation_angle) {
    double angle = std::fmod(rotation, 360.0);
    if (angle > 180.0) angle -= 360.0;
    else if (angle < -180.0) angle += 360.0;
    runtime->rotation_angle = angle;
    const double rad = angle * (flight::pi / 180.0);
    runtime->rotation_sine = std::sin(rad);
    runtime->rotation_cosine = std::cos(rad);
  }
  if (!runtime->local_matrix) runtime->local_matrix = flight::geometry::create_matrix();
  auto m = *runtime->local_matrix;
  const double sx = value.template operator()<flight::RowKey<"scaleX">>();
  const double sy = value.template operator()<flight::RowKey<"scaleY">>();
  const double kx = value.template operator()<flight::RowKey<"skewX">>();
  const double ky = value.template operator()<flight::RowKey<"skewY">>();
  if (kx == 0 && ky == 0) {
    m->a = runtime->rotation_cosine * sx; m->b = runtime->rotation_sine * sx;
    m->c = -runtime->rotation_sine * sy; m->d = runtime->rotation_cosine * sy;
  } else {
    const double ry = (runtime->rotation_angle + ky) * (flight::pi / 180.0);
    const double rx = (runtime->rotation_angle + kx) * (flight::pi / 180.0);
    m->a = std::cos(ry) * sx; m->b = std::sin(ry) * sx;
    m->c = -std::sin(rx) * sy; m->d = std::cos(rx) * sy;
  }
  const double px = value.template operator()<flight::RowKey<"pivotX">>();
  const double py = value.template operator()<flight::RowKey<"pivotY">>();
  m->tx = value.template operator()<flight::RowKey<"x">>() - (m->a * px + m->c * py);
  m->ty = value.template operator()<flight::RowKey<"y">>() - (m->b * px + m->d * py);
  runtime->local_transform_using_local_transform_id = runtime->local_transform_id;
  return m;
}
